-- 时间旅行（Time Travel）：查询表在历史某个时刻的快照
-- Delta Lake 语法：
SELECT * FROM sales_delta VERSION AS OF 123456;
SELECT * FROM sales_delta TIMESTAMP AS OF '2024-03-01 10:00:00';

-- Iceberg（Spark SQL）语法：
SELECT * FROM sales_iceberg VERSION AS OF 789012;
SELECT * FROM sales_iceberg TIMESTAMP AS OF '2024-03-01';

-- 典型场景：昨天的报表算错了，直接查昨天的数据快照对账，不用重新拉数
